local handlers = {}

if isClient then
    Plugins.Require("video", "common.GMVideo")
    Plugins.Require("video", "common.config.VideoDefine")
    Plugins.Require("video", "common.config.VideoEffectConfig")

    BaseListener.registerCallBack(CEvents.GameDestroyEvent, function()
        ---@type UIVideoMainLayout
        local GUIVideoMain = GUIManager:getLayout("VideoMain.json")
        if not GUIVideoMain then
            return
        end
        ---@type RecorderUtil
        local RecorderUtil = T(Global, "RecorderUtil")
        Blockman.Instance().m_gameSettings:setLutTextureName("")
        RecorderUtil:setWeather(nil, true)
        RecorderUtil:removeAllUiEffects()
        RecorderUtil:enableTopBottomCover(true)
        RecorderUtil:enablePatternTorch(true)
        RecorderUtil:enableSpeedLine(true)
    end)
end

function handlers.openVideo()
    print("--------------------openVideo-------------")
    ---@type UIVideoMainLayout
    local GUIVideoMain = GUIManager:getLayout("VideoMain.json")
    if not GUIVideoMain then
        GUIVideoMain = UIHelper.newGameGUILayout("GUIVideoMain")
    end
    GUIVideoMain:show()
end

function handlers.closeUiHide()
    ---@type UIVideoMainLayout
    local GUIVideoMain = GUIManager:getLayout("VideoMain.json")
    if GUIVideoMain and GUIVideoMain.isHideUI then
        GUIVideoMain:setHideUI(false)
    end
end

return function(name, ...)
    if type(handlers[name]) ~= "function" then
        return
    end
    handlers[name](...)
end